/* Extend the existing saved-ID store rather than create a second product list. */
(()=>{'use strict';const saved=window.PCP_SAVED;if(!saved)return;
const message=text=>{const node=document.querySelector('[data-watch-status]');if(node)node.textContent=text};
// Keep the previous preview key as a reversible local migration backup.
try{const old=JSON.parse(localStorage.getItem('pcp-watchlist-v1')||'[]');if(localStorage.getItem('pcp-watchlist-migration-v1')!=='complete'&&Array.isArray(old)&&old.length){const ids=old.filter(r=>r&&/^[a-zA-Z0-9_-]{1,120}$/.test(r.id)).map(r=>'product_'+r.id),current=saved.read(),merged=[...new Set([...current,...ids])];if(merged.length>100)message('Some previous watched IDs exceed the saved-list limit; the original local list is retained.');else if(merged.length===current.length||saved.write(merged))localStorage.setItem('pcp-watchlist-migration-v1','complete')}}catch{message('The previous local watchlist could not be imported. Existing saved items are retained.')}
const product=document.querySelector('#shopping-product');if(product){try{const p=JSON.parse(product.textContent);if(/^[a-zA-Z0-9_-]{1,120}$/.test(p.id)){const button=document.querySelector('[data-save-id="product_'+p.id+'"]'),host=document.querySelector('#buy');if(button&&host){button.dataset.saveType='product';host.append(button);saved.refresh()}}}catch{}}
document.querySelector('[data-watch-export]')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify({schema:'pcp-saved-v1',ids:saved.read(),limitations:['Local saved IDs only. No price alert or background price checking is active.','Build revisions are exported separately from the PC builder.']},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pc-part-saved-items.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);message('Saved IDs exported. Build revisions, private notes and email addresses are not included.');});
})();
